"use client";

import * as React from "react";
import {
  Area,
  AreaChart,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { cn } from "@/lib/utils";

export type TickerPoint = { time: number; price: number };

type Props = {
  data: TickerPoint[];
  variant?: "sparkline" | "full";
  className?: string;
  height?: number;
  formatTime?: (ms: number) => string;
  formatPrice?: (n: number) => string;
};

const defaultFormatPrice = (n: number) =>
  n >= 1 ? `$${n.toLocaleString(undefined, { maximumFractionDigits: 2 })}` : `$${n.toPrecision(4)}`;

const defaultFormatTime = (ms: number) => {
  const d = new Date(ms);
  return d.toLocaleString();
};

export function TickerChart({
  data,
  variant = "sparkline",
  className,
  height,
  formatTime = defaultFormatTime,
  formatPrice = defaultFormatPrice,
}: Props) {
  const direction: "bull" | "bear" =
    data.length >= 2 && data[data.length - 1]!.price >= data[0]!.price ? "bull" : "bear";

  const stroke = direction === "bull" ? "var(--color-bull)" : "var(--color-bear)";
  const fillId = `mt-fill-${direction}-${React.useId().replace(/:/g, "")}`;

  if (variant === "sparkline") {
    return (
      <div className={cn("w-full", className)} style={{ height: height ?? 40 }}>
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 2, bottom: 2, left: 0, right: 0 }}>
            <defs>
              <linearGradient id={fillId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={stroke} stopOpacity={0.5} />
                <stop offset="100%" stopColor={stroke} stopOpacity={0} />
              </linearGradient>
            </defs>
            <Area
              dataKey="price"
              type="monotone"
              stroke={stroke}
              strokeWidth={1.5}
              fill={`url(#${fillId})`}
              isAnimationActive={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    );
  }

  return (
    <div className={cn("w-full", className)} style={{ height: height ?? 280 }}>
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data} margin={{ top: 12, right: 16, left: 0, bottom: 12 }}>
          <XAxis
            dataKey="time"
            tickFormatter={formatTime}
            stroke="var(--color-muted-foreground)"
            tick={{ fontSize: 11 }}
            tickLine={false}
            axisLine={false}
          />
          <YAxis
            tickFormatter={formatPrice}
            stroke="var(--color-muted-foreground)"
            tick={{ fontSize: 11 }}
            tickLine={false}
            axisLine={false}
            width={64}
            domain={["dataMin", "dataMax"]}
          />
          <Tooltip
            cursor={{ stroke: "var(--color-muted-foreground)", strokeDasharray: 4 }}
            contentStyle={{
              background: "var(--color-popover)",
              border: "1px solid var(--color-border)",
              borderRadius: 8,
              fontSize: 12,
            }}
            labelFormatter={(ms) => formatTime(ms as number)}
            formatter={(v) => [formatPrice(v as number), "Price"]}
          />
          <ReferenceLine
            y={data[0]?.price}
            stroke="var(--color-muted-foreground)"
            strokeDasharray="3 3"
            opacity={0.4}
          />
          <Line
            dataKey="price"
            type="monotone"
            stroke={stroke}
            strokeWidth={2}
            dot={false}
            isAnimationActive={false}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

type TimeRangeProps<R extends string> = {
  value: R;
  ranges: readonly R[];
  onChange: (r: R) => void;
  className?: string;
};

export function TimeRangeSelector<R extends string>({
  value,
  ranges,
  onChange,
  className,
}: TimeRangeProps<R>) {
  return (
    <div
      className={cn("inline-flex rounded-md border border-border bg-card p-0.5 text-xs", className)}
    >
      {ranges.map((r) => (
        <button
          key={r}
          type="button"
          onClick={() => onChange(r)}
          className={cn(
            "rounded px-2 py-1 transition-colors",
            value === r
              ? "bg-accent text-accent-foreground"
              : "text-muted-foreground hover:text-foreground",
          )}
        >
          {r}
        </button>
      ))}
    </div>
  );
}
